import json, os, stat, sys
rep = {}
for fd in (0, 1, 2):
    st = os.fstat(fd)
    rep[str(fd)] = {'dev': st.st_dev, 'ino': st.st_ino, 'fmt': stat.S_IFMT(st.st_mode),
                    'isatty': os.isatty(fd), 'tty': os.ttyname(fd) if os.isatty(fd) else None}
open(sys.argv[1], 'w').write(json.dumps(rep))
os.write(1, b'child-out\n'); os.write(2, b'child-err\n')
